INSERT INTO adhkar (context_code, category, text_ar, text_nl, text_en, how_to_apply_ar, how_to_apply_nl, how_to_apply_en, reward_ar, reward_nl, reward_en, guidance_ar, guidance_nl, guidance_en, repetitions, sort_order) VALUES
('quran_duas', 'event', '﴿رَبِّ اشْرَحْ لِي صَدْرِي ۝٢٥ وَيَسِّرْ لِي أَمْرِي ۝٢٦ وَاحْلُلْ عُقْدَةً مِّن لِّسَانِي ۝٢٧ يَفْقَهُوا قَوْلِي﴾', 'Vertaling van de betekenis: Mijn Heer, verruim voor mij mijn borst, maak mijn zaak gemakkelijk voor mij en ontknoop de knoop van mijn tong, zodat zij mijn woorden begrijpen — de smeekbede van Moesaa.', 'Meaning: My Lord, expand for me my chest, ease for me my task, and untie the knot from my tongue so they may understand my speech — the supplication of Moesaa.', 'قالها نوح عليه السلام في ختام دعوته؛ فتقال في ختام المجالس والأعمال، ويدخل فيها كل من دخل بيتك مؤمنا.', 'Nooh (vrede zij met hem) zei haar aan het einde van zijn oproep; zij wordt dus gezegd bij het afsluiten van bijeenkomsten en werken, en zij omvat ieder die je huis gelovig binnentreedt.', 'Nooh (peace be upon him) said it at the end of his call; so it is said at the conclusion of gatherings and works, and it includes everyone who enters your house as a believer.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'دعاء موسى عند المهمة', 'onbeperkt', 'unrestricted', 1, 321),('quran_duas', 'event', '﴿رَّبِّ زِدْنِي عِلْمًا﴾', 'Vertaling van de betekenis: Mijn Heer, vermeerder mij in kennis.', 'Meaning: My Lord, increase me in knowledge.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الدعاء بزيادة العلم', 'onbeperkt', 'unrestricted', 1, 322),('quran_duas', 'event', '﴿لَّا إِلَهَ إِلَّا أَنتَ سُبْحَانَكَ إِنِّي كُنتُ مِنَ الظَّالِمِينَ﴾', 'Er is geen god behalve U, verheven bent U; waarlijk, ik behoorde tot de onrechtplegers — geen moslim smeekt hiermee over iets of Allaah verhoort hem.', 'None has the right to be worshipped except You; glory be to You, indeed I was among the wrongdoers — no Muslim supplicates with it for anything except that Allaah answers him.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'دعوة ذي النون', 'onbeperkt', 'unrestricted', 1, 323),('quran_duas', 'event', '﴿رَّبِّ أَعُوذُ بِكَ مِنْ هَمَزَاتِ الشَّيَاطِينِ ۝٩٧ وَأَعُوذُ بِكَ رَبِّ أَن يَحْضُرُونِ﴾', 'Vertaling van de betekenis: Mijn Heer, ik zoek toevlucht bij U tegen de influisteringen van de shayaatien, en ik zoek toevlucht bij U, mijn Heer, dat zij bij mij aanwezig zijn.', 'Meaning: My Lord, I seek refuge in You from the promptings of the devils, and I seek refuge in You, my Lord, lest they be present with me.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الاستعاذة من همزات الشياطين', 'onbeperkt', 'unrestricted', 1, 324),('quran_duas', 'event', '﴿رَبَّنَا آمَنَّا فَاغْفِرْ لَنَا وَارْحَمْنَا وَأَنتَ خَيْرُ الرَّاحِمِينَ﴾', 'Vertaling van de betekenis: Onze Heer, wij geloven; vergeef ons dus en wees ons genadig, en U bent de Beste der barmhartigen.', 'Meaning: Our Lord, we believe, so forgive us and have mercy on us, and You are the best of the merciful.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الدعاء بالمغفرة والرحمة', 'onbeperkt', 'unrestricted', 1, 325),('quran_duas', 'event', '﴿رَبَّنَا اصْرِفْ عَنَّا عَذَابَ جَهَنَّمَ إِنَّ عَذَابَهَا كَانَ غَرَامًا﴾', 'Vertaling van de betekenis: Onze Heer, wend de bestraffing van djahannam van ons af; waarlijk, haar bestraffing is blijvend.', 'Meaning: Our Lord, avert from us the punishment of Hell; indeed its punishment is ever adhering.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الاستعاذة من عذاب جهنم', 'onbeperkt', 'unrestricted', 1, 326),('quran_duas', 'event', '﴿رَبَّنَا هَبْ لَنَا مِنْ أَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ أَعْيُنٍ وَاجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا﴾', 'Vertaling van de betekenis: Onze Heer, schenk ons van onze echtgenotes en ons nageslacht verkoeling van de ogen, en maak ons tot voorgangers van de godsvrezenden.', 'Meaning: Our Lord, grant us from our spouses and offspring comfort of the eyes, and make us leaders for the God-fearing.', 'دعاء عباد الرحمن؛ يقال في سؤال صلاح الزوج والذرية، ويلحق بأدعية قسم المناسبات.', 'De smeekbede van de dienaren van de Barmhartige; gezegd bij het vragen om de deugdzaamheid van echtgenoot en nageslacht, en zij sluit aan bij de smeekbeden van de rubriek gelegenheden.', 'The supplication of the servants of the Most Merciful; said when asking for the righteousness of spouse and offspring, joining the supplications of the occasions section.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الدعاء بصلاح الأهل والذرية', 'onbeperkt', 'unrestricted', 1, 327),('quran_duas', 'event', '﴿رَبِّ أَوْزِعْنِي أَنْ أَشْكُرَ نِعْمَتَكَ الَّتِي أَنْعَمْتَ عَلَيَّ وَعَلَى وَالِدَيَّ وَأَنْ أَعْمَلَ صَالِحًا تَرْضَاهُ وَأَدْخِلْنِي بِرَحْمَتِكَ فِي عِبَادِكَ الصَّالِحِينَ﴾', 'Vertaling van de betekenis: Mijn Heer, spoor mij aan Uw gunst te danken die U mij en mijn ouders heeft geschonken, en goede daden te verrichten waarover U tevreden bent, en laat mij door Uw barmhartigheid binnentreden onder Uw rechtschapen dienaren — de smeekbede van Sulaymaan.', 'Meaning: My Lord, enable me to be grateful for Your favour upon me and my parents, and to do righteousness pleasing to You, and admit me by Your mercy among Your righteous servants — Sulaymaan''s supplication.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الدعاء بشكر النعمة', 'onbeperkt', 'unrestricted', 1, 328),('quran_duas', 'event', '﴿رَبِّ إِنِّي لِمَا أَنزَلْتَ إِلَيَّ مِنْ خَيْرٍ فَقِيرٌ﴾', 'Vertaling van de betekenis: Mijn Heer, waarlijk, ik ben behoeftig aan al het goede dat U tot mij neerzendt [al-Qasas 24] — de smeekbede van Moesaa in zijn armoede.', 'Meaning: My Lord, indeed I am in need of whatever good You send down to me [al-Qasas 24] — the supplication of Moesaa in his poverty.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'دعاء يوسف بحسن الخاتمة', 'onbeperkt', 'unrestricted', 1, 329),('quran_duas', 'event', '﴿رَبِّ انصُرْنِي عَلَى الْقَوْمِ الْمُفْسِدِينَ﴾', 'Vertaling van de betekenis: Mijn Heer, help mij tegen het verderfzaaiende volk.', 'Meaning: My Lord, help me against the corrupting people.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الدعاء على المفسدين', 'onbeperkt', 'unrestricted', 1, 330),('quran_duas', 'event', '﴿رَبِّ هَبْ لِي مِنَ الصَّالِحِينَ﴾', 'Vertaling van de betekenis: Mijn Heer, schenk mij (een kind) uit de rechtschapenen — de smeekbede van Ibraahiem.', 'Meaning: My Lord, grant me (a child) from among the righteous — Ibraahiem''s supplication.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الدعاء بالولد الصالح', 'onbeperkt', 'unrestricted', 1, 331),('quran_duas', 'event', '﴿رَبِّ أَوْزِعْنِي أَنْ أَشْكُرَ نِعْمَتَكَ الَّتِي أَنْعَمْتَ عَلَيَّ وَعَلَى وَالِدَيَّ وَأَنْ أَعْمَلَ صَالِحًا تَرْضَاهُ وَأَصْلِحْ لِي فِي ذُرِّيَّتِي إِنِّي تُبْتُ إِلَيْكَ وَإِنِّي مِنَ الْمُسْلِمِينَ﴾', 'Vertaling van de betekenis: Mijn Heer, spoor mij aan Uw gunst te danken die U mij en mijn ouders heeft geschonken, en goede daden te verrichten waarover U tevreden bent, en maak mijn nageslacht goed voor mij; ik keer berouwvol tot U terug en ik behoor tot de moslims — de smeekbede van wie de veertig bereikt.', 'Meaning: My Lord, enable me to be grateful for Your favour upon me and my parents, and to work righteousness pleasing to You, and set right for me my offspring; I repent to You and I am of the Muslims — the supplication of one reaching forty.', 'قيّدها الله ببلوغ الأشد وأربعين سنة؛ فيتأكد الدعاء بها لمن بلغ الأربعين: شكرا وعملا وإصلاحا للذرية وتوبة.', 'Allaah bond haar aan het bereiken van de volle kracht en veertig jaar; de smeekbede ermee is dus nadrukkelijk voor wie de veertig bereikt: als dank, werk en het goedmaken van het nageslacht.', 'Allaah bound it to reaching full strength and forty years; so supplicating with it is emphatic for whoever reaches forty: as gratitude, work and setting the offspring right.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الدعاء عند بلوغ الأربعين', 'onbeperkt', 'unrestricted', 1, 332),('quran_duas', 'event', '﴿رَبَّنَا اغْفِرْ لَنَا وَلِإِخْوَانِنَا الَّذِينَ سَبَقُونَا بِالْإِيمَانِ وَلَا تَجْعَلْ فِي قُلُوبِنَا غِلًّا لِّلَّذِينَ آمَنُوا رَبَّنَا إِنَّكَ رَءُوفٌ رَّحِيمٌ﴾', 'Vertaling van de betekenis: Onze Heer, vergeef ons en onze broeders die ons in het geloof zijn voorgegaan, en plaats in onze harten geen wrok jegens hen die geloven; onze Heer, U bent Meest Zachtmoedig, Genadevol.', 'Meaning: Our Lord, forgive us and our brothers who preceded us in faith, and place not in our hearts rancour toward those who believe; our Lord, You are Kind, Merciful.', 'دعاء من جاء بعد الصحابة؛ فهو ورد المؤمن للسابقين بالإيمان، ويقال عند فتن الطعن في الصحابة خاصة: طلبا لسلامة القلب من الغل لهم.', 'De smeekbede van wie na de metgezellen kwam; het is de wird van de gelovige voor wie hem in het geloof voorgingen, en wordt gezegd bij beproevingen van het bekritiseren van de metgezellen in het bijzonder: vragend om een zuiver hart jegens hen.', 'The supplication of those who came after the companions; it is the believer''s wird for those who preceded him in faith, said especially at trials of criticising the companions: asking for a heart sound toward them.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الدعاء للمؤمنين وسلامة القلب', 'onbeperkt', 'unrestricted', 1, 333),('quran_duas', 'event', '﴿رَّبَّنَا عَلَيْكَ تَوَكَّلْنَا وَإِلَيْكَ أَنَبْنَا وَإِلَيْكَ الْمَصِيرُ ۝٤ رَبَّنَا لَا تَجْعَلْنَا فِتْنَةً لِّلَّذِينَ كَفَرُوا وَاغْفِرْ لَنَا رَبَّنَا إِنَّكَ أَنتَ الْعَزِيزُ الْحَكِيمُ﴾', 'Vertaling van de betekenis: Onze Heer, op U vertrouwen wij, tot U keren wij berouwvol terug en tot U is de terugkeer. Onze Heer, maak ons niet tot een beproeving voor hen die ongelovig zijn, en vergeef ons, onze Heer; waarlijk, U bent de al-Machtige (al-3aziez), de al-Wijze (al-Hakiem).', 'Meaning: Our Lord, upon You we rely, to You we turn, and to You is the final return. Our Lord, make us not a trial for those who disbelieve, and forgive us, our Lord; indeed You are al-3azeez (the Almighty), al-Hakeem (the All-Wise).', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'دعاء التوكل والإنابة', 'onbeperkt', 'unrestricted', 1, 334),('quran_duas', 'event', '﴿رَبَّنَا أَتْمِمْ لَنَا نُورَنَا وَاغْفِرْ لَنَا إِنَّكَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ﴾', 'Vertaling van de betekenis: Onze Heer, vervolmaak voor ons ons licht en vergeef ons; waarlijk, U bent tot alles in staat.', 'Meaning: Our Lord, perfect for us our light and forgive us; indeed You are able to do all things.', 'هي دعاء الراسخين في العلم عند المتشابهات؛ فتقال عند الفتن والشبهات وتقلب الأحوال.', 'Zij is de smeekbede van de standvastigen in kennis bij de meerduidige (verzen); zij wordt dus gezegd bij beproevingen, twijfels en het wisselen van toestanden.', 'It is the supplication of those firm in knowledge at the ambiguous (verses); so it is said at trials, doubts and the changing of states.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الدعاء بإتمام النور', 'onbeperkt', 'unrestricted', 1, 335),('quran_duas', 'event', '﴿رَّبِّ اغْفِرْ لِي وَلِوَالِدَيَّ وَلِمَن دَخَلَ بَيْتِيَ مُؤْمِنًا وَلِلْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ﴾', 'Vertaling van de betekenis: Mijn Heer, vergeef mij en mijn ouders en wie mijn huis gelovig binnentreedt, en de gelovige mannen en de gelovige vrouwen — de smeekbede van Noeh.', 'Meaning: My Lord, forgive me and my parents and whoever enters my house as a believer, and the believing men and women — Nooh''s supplication.', 'قالها نوح عليه السلام في ختام دعوته؛ فتقال في ختام المجالس والأعمال، ويدخل فيها كل من دخل بيتك مؤمنا.', 'Nooh (vrede zij met hem) zei haar aan het einde van zijn oproep; zij wordt dus gezegd bij het afsluiten van bijeenkomsten en werken, en zij omvat ieder die je huis gelovig binnentreedt.', 'Nooh (peace be upon him) said it at the end of his call; so it is said at the conclusion of gatherings and works, and it includes everyone who enters your house as a believer.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الدعاء للوالدين والمؤمنين', 'onbeperkt', 'unrestricted', 1, 336),('comprehensive', 'general', '«اللَّهُمَّ آتِنَا فِي الدُّنْيَا حَسَنَةً، وَفِي الْآخِرَةِ حَسَنَةً، وَقِنَا عَذَابَ النَّارِ»', 'O Allaah, schenk ons in dit leven het goede en in het Hiernamaals het goede, en bescherm ons tegen de bestraffing van het Vuur — de meest voorkomende smeekbede van de Profeet (vrede en zegeningen zij met hem).', 'O Allaah, give us good in this world and good in the Hereafter, and protect us from the punishment of the Fire — the Prophet''s most frequent supplication (peace and blessings be upon him).', '', '', '', 'كان أكثر دعائه صلى الله عليه وسلم؛ وفي قصة الفرخ أن الله شفى صاحبها لما قالها.', 'Het was zijn meest voorkomende smeekbede (vrede en zegeningen zij met hem); en in het verhaal van ''de kuikenzwakke'' man genas Allaah hem toen hij haar zei.', 'It was his most frequent supplication (peace and blessings be upon him); and in the account of the frail man Allaah cured him when he said it.', 'كان أكثر دعائه ﷺ', 'onbeperkt', 'unrestricted', 1, 337),('comprehensive', 'general', '«اللَّهُمَّ إِنِّي أَسْأَلُكَ الْهُدَى، وَالتُّقَى، وَالْعَفَافَ، وَالْغِنَى»', 'O Allaah, ik vraag U om leiding, godsvrees, kuisheid en onafhankelijkheid.', 'O Allaah, I ask You for guidance, piety, chastity and sufficiency.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الدعاء بالهدى والتقى والعفاف والغنى', 'onbeperkt', 'unrestricted', 1, 338),('comprehensive', 'general', '«اللَّهُمَّ أَصْلِحْ لِي دِينِيَ الَّذِي هُوَ عِصْمَةُ أَمْرِي، وَأَصْلِحْ لِي دُنْيَايَ الَّتِي فِيهَا مَعَاشِي، وَأَصْلِحْ لِي آخِرَتِيَ الَّتِي فِيهَا مَعَادِي، وَاجْعَلِ الْحَيَاةَ زِيَادَةً لِي فِي كُلِّ خَيْرٍ، وَاجْعَلِ الْمَوْتَ رَاحَةً لِي مِنْ كُلِّ شَرٍّ»', 'O Allaah, breng mijn geloof in orde, dat de bescherming van mijn zaak is; breng mijn wereldse leven in orde, waarin mijn levensonderhoud ligt; en breng mijn Hiernamaals in orde, waarheen mijn terugkeer is. Maak het leven voor mij een vermeerdering in al het goede, en maak de dood voor mij een rust van al het kwade.', 'O Allaah, set right my religion, which is the safeguard of my affair; set right my worldly life, in which is my livelihood; and set right my Hereafter, to which is my return. Make life for me an increase in every good, and make death a relief for me from every evil.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الدعاء بصلاح الدين والدنيا والآخرة', 'onbeperkt', 'unrestricted', 1, 339),('comprehensive', 'general', '«اللَّهُمَّ اغْفِرْ لِي خَطِيئَتِي وَجَهْلِي، وَإِسْرَافِي فِي أَمْرِي، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي، اللَّهُمَّ اغْفِرْ لِي جِدِّي وَهَزْلِي، وَخَطَئِي وَعَمْدِي، وَكُلُّ ذَلِكَ عِنْدِي، اللَّهُمَّ اغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ، وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي، أَنْتَ الْمُقَدِّمُ وَأَنْتَ الْمُؤَخِّرُ، وَأَنْتَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ»', 'O Allaah, vergeef mij mijn fout en mijn onwetendheid, mijn buitensporigheid in mijn zaak en wat U beter weet dan ik. O Allaah, vergeef mij mijn ernst en mijn scherts, mijn vergissing en mijn opzet — en dat alles is bij mij aanwezig. O Allaah, vergeef mij wat ik eerder deed en wat later kwam, wat ik verborg en wat ik openlijk deed, en wat U beter weet dan ik. U bent Degene Die vooruit doet gaan en Die uitstelt, en U bent tot alles in staat.', 'O Allaah, forgive me my fault and my ignorance, my excess in my affair, and what You know better than I. O Allaah, forgive me my earnest and my jest, my mistake and my deliberate act — and all of that is with me. O Allaah, forgive me what I sent before and what I left behind, what I hid and what I declared, and what You know better than I. You are the One who advances and the One who delays, and You are able to do all things.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الاستغفار الجامع', 'onbeperkt', 'unrestricted', 1, 340);